B.a9F=s([B.aj3],t.NL)
B.apN=new A.b_("D\u011bda Bohou\u0161 dnes slav\xed sedmdes\xe1t\xe9 narozeniny. D\u016fm je pln\xfd p\u0159\xedbuzn\xfdch, von\xed tu sv\xed\u010dkov\xe1 a dort a v\u0161ude cinkaj\xed skleni\u010dky. Teta Jarmila \u0161t\xedpe do tv\xe1\u0159\xed ka\u017ed\xe9ho, kdo se nestihne schovat. Str\xfdc Pepa u\u017e pot\u0159et\xed vypr\xe1v\xed o hypot\xe9k\xe1ch. A d\u011bda sed\xed v \u010dele stolu a usm\xedv\xe1 se pod vousy.")
B.er=new A.kv("K","klara","")
B.ai_=s(["\u201eTohle je ofici\xe1ln\u011b nejnudn\u011bj\u0161\xed oslava na sv\u011bt\u011b. Spo\u010d\xedtala jsem to. Str\xfdc \u0159ekl slovo hypot\xe9ka dvaa\u010dty\u0159icetkr\xe1t.\u201c"],t.s)
B.b6Y=new A.a7(B.er,B.ai_,!1)
B.f9=new A.kv("T","tobi","")
B.afK=s(["\u201eTeta m\u011b \u0161t\xedpla u\u017e p\u011btkr\xe1t. Za chv\xedli budu m\xedt tv\xe1\u0159e jako dv\u011b raj\u010data.\u201c"],t.s)
B.b9u=new A.a7(B.f9,B.afK,!1)
B.a88=s(["\u201eJako dv\u011b mal\xe1 kysel\xe1 raj\u010d\xe1tka.\u201c"],t.s)
B.b8_=new A.a7(B.er,B.a88,!1)
B.aa2=s(["\u201eNejsem kysel\xfd!\u201c"],t.s)
B.b9V=new A.a7(B.f9,B.aa2,!1)
B.aqo=new A.b_("Kl\xe1ra se rozhl\xe9dne a uk\xe1\u017ee ke schod\u016fm. Vedou nahoru, a\u017e pod st\u0159echu. Na p\u016fdu, kam nikdo nechod\xed.")
B.al1=s(["\u201eMiz\xedme. Hned te\u010f.\u201c"],t.s)
B.b7c=new A.a7(B.er,B.al1,!1)
B.a9D=s([B.apN,B.b6Y,B.b9u,B.b8_,B.b9V,B.aqo,B.b7c],t.a)
B.baB=new A.cD("story_01",B.a9D)
B.aqI=new A.b_("Kl\xe1ra, Tobi a ty cupit\xe1te po schodech nahoru. Dup, dup, dup. A za v\xe1mi \u0165apkaj\xed \u010dty\u0159i tlapky. Pes Ferda p\u0159ece nebude chyb\u011bt u \u017e\xe1dn\xe9 lump\xe1rny!")
B.adj=s(["\u201eJ\xe1 prvn\xed!\u201c"],t.s)
B.b7P=new A.a7(B.f9,B.adj,!1)
B.aiS=s(["\u201eNe, j\xe1!\u201c"],t.s)
B.b7e=new A.a7(B.er,B.aiS,!1)
B.ar0=new A.b_("Dve\u0159e na p\u016fdu zavrzaj\xed. Vrrrrz. Je tu \u0161ero a ve sv\u011btle z ok\xe9nka tan\u010d\xed prach. U st\u011bny stoj\xed reg\xe1l se star\xfdmi plechovkami. Na tr\xe1mu vis\xed kalend\xe1\u0159 s traktorem. A uprost\u0159ed stoj\xed velk\xe1 zelen\xe1 bedna s \u010derven\xfdm p\xedsmenem B.")
B.afJ=s(["\u201e\u201aNEOTEV\xcdRAT!\u2018 \u2026 A pod t\xedm malink\xfdmi p\xedsmenky: \u201akrom\u011b pr\u016fzkumn\xedk\u016f\u2018.\u201c"],t.s)
B.b6Z=new A.a7(B.f9,B.afJ,!1)
B.aj1=s(["\u201eKrom\u011b pr\u016fzkumn\xedk\u016f. To jsme p\u0159ece my.\u201c"],t.s)
B.b84=new A.a7(B.er,B.aj1,!1)
B.aqz=new A.b_("Ferda zavrt\xed ocasem a k\xfdchne. Hep\u010d\xed! Na v\xedku bedny je ale kulat\xfd z\xe1mek. A kl\xed\u010d nikde.")
B.abC=s([B.aqI,B.b7P,B.b7e,B.ar0,B.b6Z,B.b84,B.aqz],t.a)
B.baO=new A.cD("story_02",B.abC)
B.ar_=new A.b_("Cvak! V\xedko bedny se zvedne a vylet\xed z n\xed oblak prachu. Puf! V\u0161ichni k\xfdchnete najednou. Hep\u010d\xed! Hep\u010d\xed! Haf!")
B.apQ=new A.b_("Uvnit\u0159 je hromada pap\xedrov\xfdch \xfatr\u017ek\u016f. Star\xe9 dopisy, se\u0161ity, kousky obr\xe1zk\u016f. Najednou se hromada pohne. A z pap\xedr\u016f vyklouzne mal\xe1 \u0161ed\xe1 my\u0161!")
B.ahk=s(["\u201e\xcd\xed\xed\xed! My\u0161!\u201c"],t.s)
B.b7U=new A.a7(B.f9,B.ahk,!1)
B.aqy=new A.b_("My\u0161 prob\u011bhne Ferdovi mezi tlapkami a zmiz\xed pod tr\xe1mem. A Ferda? Velk\xfd state\u010dn\xfd hl\xedda\u010d se schov\xe1 za Kl\xe1ru a cel\xfd se t\u0159ese.")
B.ahV=s(["\u201eFerdo, ty jsi ale hrdina. Boj\xed\u0161 se my\u0161i, kter\xe1 je men\u0161\xed ne\u017e tvoje miska.\u201c"],t.s)
B.b9c=new A.a7(B.er,B.ahV,!1)
B.a9K=s(["\u201eJ\xe1 jsem se neb\xe1l. Jenom jsem ji\u2026 hlasit\u011b pozdravil.\u201c"],t.s)
B.b7g=new A.a7(B.f9,B.a9K,!1)
B.adU=s([B.ar_,B.apQ,B.b7U,B.aqy,B.b9c,B.b7g],t.a)
B.bb_=new A.cD("story_03",B.adU)
B.aeI=s(["\u201ePo\u010dkejte. V kalend\xe1\u0159i byl zakrou\u017ekovan\xfd jednadvac\xe1t\xfd z\xe1\u0159\xed. A dneska je\u2026 dneska je p\u0159ece jednadvac\xe1t\xe9ho z\xe1\u0159\xed! To m\xe1 d\u011bda narozeniny!\u201c"],t.s)
B.b93=new A.a7(B.er,B.aeI,!1)
B.apw=new A.b_("Kl\xe1ra se pod\xedv\xe1 na velk\xe9 \u010derven\xe9 B na v\xedku.")
B.ajR=s(["\u201eB jako Bohou\u0161. Ta bedna je d\u011bdova!\u201c"],t.s)
B.b8u=new A.a7(B.er,B.ajR,!1)
B.aq_=new A.b_("Tobi zat\xedm opatrn\u011b p\u0159eb\xedr\xe1 \xfatr\u017eky pap\xedru. Jeden je jin\xfd ne\u017e ostatn\xed. Je \u010dtvere\u010dkovan\xfd a je na n\u011bm kresba pastelkou: kousek cesti\u010dky, mal\xfd stromek a velk\xfd \u010dern\xfd k\u0159\xed\u017eek.")
B.acy=s(["\u201eKl\xe1ro\u2026 to je kousek mapy. Mapy k pokladu!\u201c"],t.s)
B.b7E=new A.a7(B.f9,B.acy,!1)
B.aj8=s(["\u201eNebo n\xe1kupn\xed seznam. K\u0159\xed\u017eek znamen\xe1 rohl\xedky.\u201c"],t.s)
B.b8V=new A.a7(B.er,B.aj8,!1)
B.ai5=s(["\u201eNa n\xe1kupn\xed seznam se p\u0159ece nekresl\xed stromky!\u201c"],t.s)
B.b98=new A.a7(B.f9,B.ai5,!1)
B.aqE=new A.b_("Jen\u017ee kde je zbytek mapy? Pap\xedr\u016f je v bedn\u011b cel\xe1 hromada. A my\u0161 si z nich ud\u011blala hn\xedzdo.")
B.ago=s([B.b93,B.apw,B.b8u,B.aq_,B.b7E,B.b8V,B.b98,B.aqE],t.a)
B.bb9=new A.cD("story_04",B.ago)
B.a9H=s([B.baB,B.baO,B.bb_,B.bb9],t.WD)
