B.aqj=new A.b_("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.cf=new A.kv(null,"marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.a9C=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.b7_=new A.a7(B.cf,B.a9C,!1)
B.br=new A.kv(null,"karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.adG=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.b8n=new A.a7(B.br,B.adG,!1)
B.aky=s([B.aqj,B.b7_,B.b8n],t.a)
B.baV=new A.cD("story_00_intro",B.aky)
B.apK=new A.b_("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.aat=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.b8j=new A.a7(B.cf,B.aat,!1)
B.aqr=new A.b_("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.aaD=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.b9A=new A.a7(B.br,B.aaD,!1)
B.co=new A.kv(null,"tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.ajw=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.b7o=new A.a7(B.co,B.ajw,!1)
B.aaV=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.b88=new A.a7(B.cf,B.aaV,!1)
B.alj=s([B.apK,B.b8j,B.aqr,B.b9A,B.b7o,B.b88],t.a)
B.bax=new A.cD("story_01a_clubhouse_arrival",B.alj)
B.aca=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.b7C=new A.a7(B.cf,B.aca,!1)
B.ae2=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.b7r=new A.a7(B.co,B.ae2,!1)
B.a8A=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.b7L=new A.a7(B.br,B.a8A,!1)
B.aay=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.b92=new A.a7(B.co,B.aay,!1)
B.a9G=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.b7m=new A.a7(B.br,B.a9G,!1)
B.a7n=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.b8o=new A.a7(B.cf,B.a7n,!1)
B.agr=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.b8x=new A.a7(B.br,B.agr,!1)
B.aki=s([B.b7C,B.b7r,B.b7L,B.b92,B.b7m,B.b8o,B.b8x],t.a)
B.bb6=new A.cD("story_01b_legend_and_time",B.aki)
B.aqW=new A.b_("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.acg=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.b7X=new A.a7(B.br,B.acg,!1)
B.abx=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.b9h=new A.a7(B.co,B.abx,!1)
B.akj=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.b7k=new A.a7(B.br,B.akj,!1)
B.afZ=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.b7N=new A.a7(B.co,B.afZ,!1)
B.a9n=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.b9q=new A.a7(B.cf,B.a9n,!1)
B.ah6=s([B.aqW,B.b7X,B.b9h,B.b7k,B.b7N,B.b9q],t.a)
B.baE=new A.cD("story_02_torn_map",B.ah6)
B.a8B=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.b8D=new A.a7(B.cf,B.a8B,!1)
B.agV=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.b8P=new A.a7(B.br,B.agV,!1)
B.aq6=new A.b_("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.ajA=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.b9U=new A.a7(B.co,B.ajA,!1)
B.ajS=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.b8R=new A.a7(B.br,B.ajS,!1)
B.aft=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.b8l=new A.a7(B.cf,B.aft,!1)
B.a9_=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.b9J=new A.a7(B.br,B.a9_,!1)
B.abK=s([B.b8D,B.b8P,B.aq6,B.b9U,B.b8R,B.b8l,B.b9J],t.a)
B.baC=new A.cD("story_03_founders_trail",B.abK)
B.apM=new A.b_("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.ab8=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.b9z=new A.a7(B.br,B.ab8,!1)
B.agk=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.b7p=new A.a7(B.co,B.agk,!1)
B.ajh=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.b8y=new A.a7(B.br,B.ajh,!1)
B.acC=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.b7A=new A.a7(B.cf,B.acC,!1)
B.aef=s([B.apM,B.b9z,B.b7p,B.b8y,B.b7A],t.a)
B.baK=new A.cD("story_04_flowers_in_mud",B.aef)
B.aqb=new A.b_("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.aa8=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.b8a=new A.a7(B.br,B.aa8,!1)
B.a7t=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.b8W=new A.a7(B.co,B.a7t,!1)
B.adc=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.b8e=new A.a7(B.br,B.adc,!1)
B.al3=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.b91=new A.a7(B.cf,B.al3,!1)
B.acZ=s([B.aqb,B.b8a,B.b8W,B.b8e,B.b91],t.a)
B.baN=new A.cD("story_05_old_oak",B.acZ)
B.aq7=new A.b_("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.ah_=s(["\u201eCo se to stalo?\u201c"],t.s)
B.b7O=new A.a7(B.br,B.ah_,!1)
B.ad0=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.b8A=new A.a7(B.cf,B.ad0,!1)
B.aai=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.b9K=new A.a7(B.br,B.aai,!1)
B.adI=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.b78=new A.a7(B.cf,B.adI,!1)
B.apT=new A.b_("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.adf=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.b8i=new A.a7(B.co,B.adf,!1)
B.aeO=s([B.aq7,B.b7O,B.b8A,B.b9K,B.b78,B.apT,B.b8i],t.a)
B.baF=new A.cD("story_06_waterfall_chest",B.aeO)
B.aqq=new A.b_("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.abA=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.b7K=new A.a7(B.co,B.abA,!1)
B.akI=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.b9t=new A.a7(B.cf,B.akI,!1)
B.aqN=new A.b_("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.aeS=s([B.aqq,B.b7K,B.b9t,B.aqN],t.a)
B.baW=new A.cD("story_07_scroll",B.aeS)
B.apC=new A.b_("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.aj4=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.b7J=new A.a7(B.br,B.aj4,!1)
B.ahC=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
B.b89=new A.a7(B.co,B.ahC,!1)
B.aav=s(["\u201eA pro\u010d to nenapsali rovnou na dve\u0159e?\u201c"],t.s)
B.b9D=new A.a7(B.br,B.aav,!1)
B.aek=s(["\u201eProto\u017ee by t\u011b nebavilo to hledat.\u201c"],t.s)
B.b9p=new A.a7(B.co,B.aek,!1)
B.afd=s(["\u201eTrp\u011blivost \u2026 ta mi nikdy moc ne\u0161la.\u201c"],t.s)
B.b9g=new A.a7(B.cf,B.afd,!1)
B.afT=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.b9n=new A.a7(B.co,B.afT,!1)
B.afP=s(["\u201eJ\xe1 \u010dek\xe1m na dort a trp\u011blivost m\xe1m.\u201c"],t.s)
B.b72=new A.a7(B.br,B.afP,!1)
B.add=s(["\u201eTo nen\xed trp\u011blivost, K\xe1jo. To je hlad.\u201c"],t.s)
B.b71=new A.a7(B.co,B.add,!1)
B.a9A=s(["\u201eA tob\u011b se zkou\u0161ka povedla. Bez tebe bychom to do z\xe1padu nestihli.\u201c"],t.s)
B.b9F=new A.a7(B.cf,B.a9A,!1)
B.agh=s([B.apC,B.b7J,B.b89,B.b9D,B.b9p,B.b9g,B.b9n,B.b72,B.b71,B.b9F],t.a)
B.baI=new A.cD("story_08_ending_dialogue",B.agh)
B.acw=s([B.baV,B.bax,B.bb6,B.baE,B.baC,B.baK,B.baN,B.baF,B.baW,B.baI],t.WD)
