B.b0s=new A.ar("sfx_forest_t04_stones_up",0.001,1,null,1)
B.b1s=new A.ar("sfx_forest_t04_thorns",0.7847358121330724,1,null,1)
B.aea=s([B.b0s,B.b1s],t.e)
B.aeb=s(["budik_T_a1","budik_L_a2","budik_C_a3","budik_R_a4","budik_B_a5"],t.s)
B.aqi=new A.b_("Je \u010dtvrtek odpoledne a t\u0159\xedda je na v\xfdlet\u011b v muzeu. Vstupn\xed hala je pln\xe1 d\u011bt\xed. Dupou po schodech, \u0161eptaj\xed si a sm\u011bj\xed se. Ema, Jon\xe1\u0161, Nela a ty se zastav\xedte u velk\xe9ho obrazu u hlavn\xedch dve\u0159\xed. Je na n\u011bm vzne\u0161en\xe1 d\xe1ma v \u0161atech, kter\xe1 sp\xed. A tv\xe1\u0159\xed se p\u011bkn\u011b nerudn\u011b.")
B.aE=new A.kv(null,"ema","assets/images/stories/museum/story/portrait_ema.webp")
B.ad7=s(["\u201e\u201aBaronka Frida von\u2026 Schla\u2026 Scho\u2026 Schovanburger.\u2018 Schovan\xfd burger? Kter\xfd bl\xe1zen by schov\xe1val burger?\u201c"],t.s)
B.b9I=new A.a7(B.aE,B.ad7,!1)
B.aI=new A.kv(null,"jonas","assets/images/stories/museum/story/portrait_jonas.webp")
B.acn=s(["\u201eSchlafenberg, Emo. \u017d\xe1dn\xfd schovan\xfd burger. Schlafen je n\u011bmecky sp\xe1t a Berg je hora. Kdy\u017e si to p\u0159elo\u017e\xed\u0161, tak je to Baronka ze Spac\xed hory.\u201c"],t.s)
B.b7a=new A.a7(B.aI,B.acn,!1)
B.aL=new A.kv(null,"nela","assets/images/stories/museum/story/portrait_nela.webp")
B.aiq=s(["\u201eTak to se na t\xe9 ho\u0159e asi moc dob\u0159e nesp\xed. Vypad\xe1, \u017ee nespala celou v\u011b\u010dnost.\u201c"],t.s)
B.b9e=new A.a7(B.aL,B.aiq,!1)
B.aqD=new A.b_("Pod jm\xe9nem baronky vis\xed je\u0161t\u011b jedna men\u0161\xed cedulka.")
B.aa7=s(["\u201e\u201aZ\xedtra r\xe1no se obraz st\u011bhuje do nov\xe9 galerie na hlavn\xedm n\xe1dra\u017e\xed.\u2018\u201c"],t.s)
B.b9v=new A.a7(B.aE,B.aa7,!1)
B.aqF=new A.b_("Jon\xe1\u0161 by p\u0159\xedsahal, \u017ee se baronka v tu chv\xedli zamra\u010dila je\u0161t\u011b v\xedc.")
B.a9B=s([B.aqi,B.b9I,B.b7a,B.b9e,B.aqD,B.b9v,B.aqF],t.a)
B.baL=new A.cD("story_01",B.a9B)
B.apW=new A.b_("Kdy\u017e exkurze skon\u010d\xed, v\u0161ichni sp\u011bchaj\xed k autobusu. Teda t\xe9m\u011b\u0159 v\u0161ichni.")
B.adx=s(["\u201ePsst. M\xe1m pl\xe1n. Schov\xe1me se v \u0161atn\u011b a muzeum bude v noci jen na\u0161e.\u201c"],t.s)
B.b9X=new A.a7(B.aE,B.adx,!1)
B.ac_=s(["\u201eTo je ten nejhor\u0161\xed pl\xe1n, jak\xfd jsem kdy sly\u0161el.\u201c"],t.s)
B.b7I=new A.a7(B.aI,B.ac_,!1)
B.apL=new A.b_("Autobus odjede. Muzeum se zav\u0159e a sv\u011btla zhasnou. V\u0161echny hodiny v muzeu se v tu chv\xedli zastav\xed a ru\u010di\u010dky sko\u010d\xed na p\u016flnoc.")
B.aiw=s(["\u201eZavol\xe1m dom\u016f, \u017ee se exkurze trochu prot\xe1hne. Hm. Nem\xe1m sign\xe1l, ani \u010d\xe1rku.\u201c"],t.s)
B.b9B=new A.a7(B.aL,B.aiw,!1)
B.aci=s(["\u201eA vstupn\xed dve\u0159e jsou zam\u010den\xe9! Jako by n\xe1s muzeum necht\u011blo pustit ven.\u201c"],t.s)
B.b77=new A.a7(B.aI,B.aci,!1)
B.apR=new A.b_("A d\u011bti poprv\xe9 napadne, \u017ee se odsud mo\u017en\xe1 nedostanou. Ani dnes. Ani nikdy.")
B.a7Q=s(["\u201eTak nebudeme \u010dekat. Prozkoum\xe1me to tu. Jenom pot\u0159ebujeme sv\u011btlo.\u201c"],t.s)
B.b8G=new A.a7(B.aE,B.a7Q,!1)
B.apV=new A.b_("V muzeu je prapodivn\xe9 ticho. V \u0161atn\u011b na zdi nejist\u011b blik\xe1 lampa. Nela najde u dve\u0159\xed star\xfd oto\u010dn\xfd vyp\xedna\u010d a zku\u0161en\u011b s n\xedm p\xe1rkr\xe1t cvakne. Lampa zaprask\xe1, zablik\xe1 a rozsv\xedt\xed se naplno.")
B.acK=s([B.apW,B.b9X,B.b7I,B.apL,B.b9B,B.b77,B.apR,B.b8G,B.apV],t.a)
B.baS=new A.cD("story_02",B.acK)
B.aqk=new A.b_("Posledn\xed sk\u0159\xed\u0148ka se s vrznut\xedm otev\u0159e a na zem vypadne sto\u010den\xfd svitek. Je to pl\xe1nek muzea, nakreslen\xfd rukou. Na druh\xe9 stran\u011b je n\u011bco naps\xe1no rozt\u0159esen\xfdm p\xedsmem.")
B.abb=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d. Nev\u011b\u0159te jej\xedmu \xfasm\u011bvu. V. T.\u2018\u201c"],t.s)
B.b9o=new A.a7(B.aI,B.abb,!1)
B.ag6=s(["\u201eKdo je V. T.? A jak\xe9mu \xfasm\u011bvu?\u201c"],t.s)
B.b9O=new A.a7(B.aE,B.ag6,!1)
B.ahO=s(["\u201eSuper. Jsme zam\u010den\xed v muzeu a dost\xe1v\xe1me podivn\xe9 vzkazy. U\u017e tu chyb\xed jen stra\u0161idlo.\u201c"],t.s)
B.b9G=new A.a7(B.aL,B.ahO,!1)
B.apO=new A.b_("Z chodby se ozve tich\xe9 \u0161ust\u011bn\xed dlouh\xfdch sukn\xed. A pak ospal\xfd \u0161epot, tak tich\xfd, \u017ee to mohl b\xfdt i pr\u016fvan:")
B.vN=new A.kv(null,"baroness","assets/images/stories/museum/story/portrait_baroness.webp")
B.ajr=s(["\u201eRuhe\u2026\u201c"],t.s)
B.b7i=new A.a7(B.vN,B.ajr,!0)
B.ach=s(["\u201eTo je n\u011bmecky. Znamen\xe1 to\u2026 ticho.\u201c"],t.s)
B.b8K=new A.a7(B.aI,B.ach,!1)
B.aqu=new A.b_("V\u0161em se zatajuje dech, proto\u017ee ta chodba je pr\xe1zdn\xe1.")
B.aqv=new A.b_("D\u011bti rychle rozlo\u017e\xed pl\xe1nek na podlaze. Jen\u017ee tma na pap\xed\u0159e se pohne. P\u0159es chodby a s\xe1ly se pomalu val\xed \u010dern\xe1 mlha a schov\xe1v\xe1 cestu. Vid\u011bt je jen \u0161atna, kde pr\xe1v\u011b stoj\xed.")
B.akm=s(["\u201eK \u010demu n\xe1m je zaml\u017een\xfd pl\xe1nek? Co s t\xedm chcete d\u011blat? Hr\xe1t na schov\xe1vanou?\u201c"],t.s)
B.b7y=new A.a7(B.aL,B.akm,!1)
B.afo=s(["\u201eTen pl\xe1nek n\xe1s n\u011bkam vede. Tak jdeme zjistit kam.\u201c"],t.s)
B.b99=new A.a7(B.aE,B.afo,!1)
B.agi=s(["\u201eEmo, po\u010dkej\u2026 Emo!\u201c"],t.s)
B.b7H=new A.a7(B.aI,B.agi,!1)
B.adM=s([B.aqk,B.b9o,B.b9O,B.b9G,B.apO,B.b7i,B.b8K,B.aqu,B.aqv,B.b7y,B.b99,B.b7H],t.a)
B.baz=new A.cD("story_03",B.adM)
B.aqZ=new A.b_("Posledn\xed dve\u0159e se otev\u0159ou a na pl\xe1nku se rozz\xe1\u0159\xed nakreslen\xe1 kost. D\u011bti stoj\xed p\u0159esn\u011b tam, kam je pl\xe1nek vedl, v s\xe1le dinosaur\u016f. Sv\xedt\xed tady jen jedna lampa. Uprost\u0159ed se ve tm\u011b r\xfdsuje n\u011bco obrovsk\xe9ho.")
B.akt=s(["\u201eEmo\u2026 to obrovsk\xe9 cosi\u2026 se pr\xe1v\u011b pohnulo?\u201c"],t.s)
B.b9_=new A.a7(B.aI,B.akt,!1)
B.aqP=new A.b_("Ze tmy se ozve tich\xe9, dlouh\xe9, kostnat\xe9 zask\u0159\xedp\xe1n\xed.")
B.aag=s(["\u201e\u0158ekn\u011bte mi, \u017ee to byly dve\u0159e.\u201c"],t.s)
B.b9m=new A.a7(B.aL,B.aag,!1)
B.akU=s([B.aqZ,B.b9_,B.aqP,B.b9m],t.a)
B.baY=new A.cD("story_04",B.akU)
B.apU=new A.b_("Posledn\xed kost zapadne na sv\xe9 m\xedsto. Kostra se zachv\u011bje, pomalu zvedne hlavu\u2026 a uk\xe1\u017ee \u010delist\xed k p\xedskovi\u0161ti v rohu s\xe1lu.")
B.afy=s(["\u201eEhm. D\u011bkujeme?\u201c"],t.s)
B.b7n=new A.a7(B.aE,B.afy,!1)
B.a8X=s(["\u201eRozum\xedm tomu spr\xe1vn\u011b, \u017ee n\xe1m pr\xe1v\u011b poradil dinosaurus?\u201c"],t.s)
B.b8p=new A.a7(B.aL,B.a8X,!1)
B.aqB=new A.b_("P\xedskovi\u0161t\u011b ale vypad\xe1 \xfapln\u011b oby\u010dejn\u011b. Hromada p\xedsku a v n\xed\u2026 nic.")
B.akF=s(["\u201e\u017d\xe1dn\xe1 cedulka. \u017d\xe1dn\xfd vzkaz. \u017d\xe1dn\xe1 \u0161ipka \u201aKl\xed\u010d je tady\u2018. To je teda pomoc.\u201c"],t.s)
B.b8w=new A.a7(B.aL,B.akF,!1)
B.ady=s([B.apU,B.b7n,B.b8p,B.aqB,B.b8w],t.a)
B.bb0=new A.cD("story_05",B.ady)
B.apD=new A.b_("P\xedskovi\u0161t\u011b se ot\u0159ese, zadun\xed a p\xedsek vyst\u0159el\xed a\u017e ke stropu. Kdy\u017e se prach usad\xed, le\u017e\xed uprost\u0159ed kr\xe1teru zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm vyryt\xe1 kost. Jon\xe1\u0161 vyt\xe1hne vzkaz.")
B.ak0=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d.\u2018 Jen\u017ee tohle nen\xed cel\xfd kl\xed\u010d. Je to jen kus!\u201c"],t.s)
B.b9S=new A.a7(B.aI,B.ak0,!1)
B.acO=s(["\u201eTak\u017ee zbytek bude schovan\xfd n\u011bkde jinde v muzeu.\u201c"],t.s)
B.b9r=new A.a7(B.aL,B.acO,!1)
B.apx=new A.b_("Lampa zablik\xe1 a zhasne. Ve tm\u011b se ozve dlouh\xe9, ospal\xe9 z\xedvnut\xed. Kdy\u017e se lampa znovu rozsv\xedt\xed, v s\xe1le nikdo nen\xed.")
B.agZ=s(["\u201eKdo z v\xe1s to byl?\u201c"],t.s)
B.b9M=new A.a7(B.aE,B.agZ,!1)
B.ajc=s(["\u201eJ\xe1 ne!\u201c"],t.s)
B.b8C=new A.a7(B.aI,B.ajc,!1)
B.ab6=s([B.apD,B.b9S,B.b9r,B.apx,B.b9M,B.b8C],t.a)
B.bb4=new A.cD("story_06",B.ab6)
B.aqp=new A.b_("D\u011bti doraz\xed do dal\u0161\xedho s\xe1lu. Je chladn\xfd a tajemn\u011b tich\xfd. Jde o egyptsk\xfd s\xe1l, je pln\xfd sarkof\xe1g\u016f, mumi\xed a soch d\xe1vn\xfdch boh\u016f. Mal\xfdm oknem pod stropem dopad\xe1 m\u011bs\xed\u010dn\xed sv\u011btlo.")
B.aee=s(["\u201eTady n\u011bkde mo\u017en\xe1 bude dal\u0161\xed kus. Jen\u017ee kde?\u201c"],t.s)
B.b7F=new A.a7(B.aI,B.aee,!1)
B.aqG=new A.b_("V rohu s\xe1lu le\u017e\xed v podlaze t\u011b\u017ek\xe1 kamenn\xe1 deska. Nehne se ani o milimetr. Ema se do n\xed op\u0159e celou vahou.")
B.aga=s(["\u201eJ\xe1 jsem v\u011bd\u011bla, \u017ee jsem m\u011bla r\xe1no sn\xedst ty dva rohl\xedky nav\xedc. \u201c"],t.s)
B.b7R=new A.a7(B.aE,B.aga,!1)
B.a8H=s([B.aqp,B.b7F,B.aqG,B.b7R],t.a)
B.baJ=new A.cD("story_07",B.a8H)
B.aqC=new A.b_("M\u011bs\xed\u010dn\xed paprsek dopadne na vytesan\xfd symbol oka a ten se rozz\xe1\u0159\xed zlat\xfdm sv\u011btlem. K\xe1men zahu\u010d\xed, deska v rohu odjede stranou a odkryje schody. Vedou hluboko pod zem.")
B.a9m=s(["\u201eSchody do nezn\xe1ma. No jasn\u011b. Schody do cukr\xe1rny to asi nebudou, co?\u201c"],t.s)
B.b8b=new A.a7(B.aL,B.a9m,!1)
B.aqf=new A.b_("Jon\xe1\u0161 se zastav\xed na prvn\xedm schodu. Nohy ho necht\u011bj\xed poslechnout. Nela mu str\u010d\xed do ruky baterku.")
B.aaR=s(["\u201eSpr\xe1vn\xfd gentleman jde p\u0159ece prvn\xed, ne?\u201c"],t.s)
B.b81=new A.a7(B.aL,B.aaR,!1)
B.aqw=new A.b_("Jon\xe1\u0161 se zhluboka nadechne.")
B.a9z=s(["\u201eD-dob\u0159e. Jdu prvn\xed. Rychle, ne\u017e si to rozmysl\xedm.\u201c"],t.s)
B.b8z=new A.a7(B.aI,B.a9z,!1)
B.adR=s([B.aqC,B.b8b,B.aqf,B.b81,B.aqw,B.b8z],t.a)
B.baP=new A.cD("story_08",B.adR)
B.aqa=new A.b_("Dole je hrobka. Je tu dusno, tma a ticho. Najednou to v\u0161ude zachrast\xed. Ze tmy vyb\u011bhnou drobn\xed brouci a rozprchnou se po cel\xe9 hrobce.")
B.ahI=s(["\u201eFuj! Brouci! \u017div\xed brouci!\u201c"],t.s)
B.b7f=new A.a7(B.aI,B.ahI,!1)
B.a9Z=s(["\u201eKlid, Jon\xe1\u0161i. Jsou to jen brouci.\u201c"],t.s)
B.b7z=new A.a7(B.aE,B.a9Z,!1)
B.aaC=s(["\u201eTo jsou skarabeov\xe9. Posv\xe1tn\xed brouci Egyp\u0165an\u016f. Ale je mi jedno, jak moc jsou posv\xe1tn\xed. Hlavn\u011b a\u0165 mi nelezou do bot.\u201c"],t.s)
B.b7l=new A.a7(B.aI,B.aaC,!1)
B.ahR=s(["\u201eJon\xe1\u0161i, te\u010f se neh\xfdbej. Jeden ti sed\xed na hlav\u011b.\u201c"],t.s)
B.b8U=new A.a7(B.aL,B.ahR,!1)
B.acx=s(["\u201eCo\u017ee?! Sundejte ho! Sundejte ho ze m\u011b!\u201c"],t.s)
B.b7T=new A.a7(B.aI,B.acx,!1)
B.aao=s(["\u201eD\u011bl\xe1m si legraci.\u201c"],t.s)
B.b8r=new A.a7(B.aL,B.aao,!1)
B.aaH=s([B.aqa,B.b7f,B.b7z,B.b7l,B.b8U,B.b7T,B.b8r],t.a)
B.baM=new A.cD("story_09",B.aaH)
B.apA=new A.b_("V\xedr v m\xedse se zpomal\xed, zastav\xed a zmiz\xed. T\u011b\u017ek\xe9 v\xedko se se sk\u0159\xedp\u011bn\xedm odsune stranou. Pod n\xedm vedou schody je\u0161t\u011b o n\u011bco hloub\u011bji.")
B.abd=s(["\u201eMuzeum m\xe1 v\xedc pater pod zem\xed ne\u017e nad n\xed. To n\xe1m nikdo na prohl\xeddce ne\u0159ekl. Asi pod\xe1m st\xed\u017enost.\u201c"],t.s)
B.b7S=new A.a7(B.aL,B.abd,!1)
B.aqS=new A.b_("D\u011bti slezou dol\u016f a ocitnou se v mal\xe9m s\xe1le. \u017d\xe1dn\xe9 dve\u0159e. Nic. Jen k\xe1men a ticho.")
B.ada=s(["\u201eNic tu nen\xed. Poj\u010fme rad\u0161i zp\xe1tky nahoru, dokud je\u0161t\u011b m\u016f\u017eeme.\u201c"],t.s)
B.b9R=new A.a7(B.aI,B.ada,!1)
B.akh=s(["\u201eNikam nejdeme. Tady n\u011bco mus\xed b\xfdt.\u201c"],t.s)
B.b87=new A.a7(B.aE,B.akh,!1)
B.adN=s(["\u201eV pohod\u011b. Jsme jen hluboko pod zem\xed, v s\xe1le bez dve\u0159\xed, uprost\u0159ed noci, v muzeu, kter\xe9 n\xe1s nechce pustit. Co by se asi tak mohlo st\xe1t?\u201c"],t.s)
B.b73=new A.a7(B.aL,B.adN,!1)
B.a7S=s([B.apA,B.b7S,B.aqS,B.b9R,B.b87,B.b73],t.a)
B.bb1=new A.cD("story_10",B.a7S)
B.aqx=new A.b_("Pod prvn\xedm podstavcem se otev\u0159ou padac\xed dv\xed\u0159ka. Podstavec propadne do tmy a z jeho m\xedsta pomalu vystoup\xed zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm oko.")
B.akW=s(["\u201eDal\u0161\xed kus!\u201c"],t.s)
B.b9l=new A.a7(B.aI,B.akW,!1)
B.aaN=s(["\u201eVid\xedte? Pohoda. Tohle d\xe1me levou zadn\xed.\u201c"],t.s)
B.b8S=new A.a7(B.aE,B.aaN,!1)
B.apB=new A.b_("D\u011bti vy\u0161plhaj\xed zp\xe1tky nahoru. Potom se odn\u011bkud z d\xe1lky ozve kovov\xe9 \u0159in\u010den\xed a slab\xfd, chraplav\xfd hlas:")
B.as=new A.kv(null,"clockmaker","assets/images/stories/museum/story/portrait_clockmaker.webp")
B.a9q=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo? Pros\xedm v\xe1s\u2026 kolik je hodin?\u201c"],t.s)
B.b9Q=new A.a7(B.as,B.a9q,!0)
B.aqQ=new A.b_("Hlas jde z ryt\xed\u0159sk\xe9ho s\xe1lu. Vstupn\xed chodbu ale zav\xedr\xe1 t\u011b\u017ek\xe1 \u017eelezn\xe1 m\u0159\xed\u017e. Za m\u0159\xed\u017e\xed je tma a v t\xe9 tm\u011b n\u011bkdo je.")
B.agW=s(["\u201eKone\u010dn\u011b! Lid\xe9! Ne\u0159\xedkejte mi, \u017ee se mi jenom zd\xe1te.\u201c"],t.s)
B.b7h=new A.a7(B.as,B.agW,!0)
B.aje=s(["\u201eKdo jste?\u201c"],t.s)
B.b8H=new A.a7(B.aE,B.aje,!1)
B.a9M=s(["\u201eTo je velmi dobr\xe1 ot\xe1zka. A\u017e na to p\u0159ijdu, \u0159eknu v\xe1m to.\u201c"],t.s)
B.b8O=new A.a7(B.as,B.a9M,!0)
B.aqt=new A.b_("D\u011bti se chyt\xed m\u0159\xed\u017ee a zat\xe1hnou ze v\u0161ech sil. Tla\u010d\xed, lomcuj\xed s n\xed, ale m\u0159\xed\u017e se nehne ani o kousek.")
B.aeC=s([B.aqx,B.b9l,B.b8S,B.apB,B.b9Q,B.aqQ,B.b7h,B.b8H,B.b8O,B.aqt],t.a)
B.baG=new A.cD("story_11",B.aeC)
B.aqs=new A.b_("M\u0159\xed\u017e s rachotem vyjede vzh\u016fru a v chodb\u011b se rozsv\xedt\xed. Na zemi tam sed\xed star\xfd mu\u017e v pracovn\xed z\xe1st\u011b\u0159e. Na nose m\xe1 br\xfdle, na \u010dele hodin\xe1\u0159skou lupu a ve vlasech pavu\u010dinu.")
B.acv=s(["\u201eD\u011bkuji. Mnohokr\xe1t d\u011bkuji. Kolik je hodin?\u201c"],t.s)
B.b8c=new A.a7(B.as,B.acv,!1)
B.aqg=new A.b_("Nela se pod\xedv\xe1 na mobil.")
B.ahb=s(["\u201eNev\xedm. Mobily ukazuj\xed 00:00, vypad\xe1 to, \u017ee se zasekly.\u201c"],t.s)
B.b8g=new A.a7(B.aL,B.ahb,!1)
B.akG=s(["\u201ePo\u0159\xe1d p\u016flnoc? To je zvl\xe1\u0161tn\xed. Kdy\u017e mne sem n\u011bkdo zav\u0159el, zastavily se v\u0161echny hodiny p\u0159esn\u011b o p\u016flnoci. Bim, bam! Kukuk! Pardon. To se mi te\u010f n\u011bjak st\xe1v\xe1.\u201c"],t.s)
B.b9P=new A.a7(B.as,B.akG,!1)
B.aq9=new A.b_("Jon\xe1\u0161 uk\xe1\u017ee na z\xe1st\u011bru.")
B.aex=s(["\u201eTady m\xe1te jmenovku. \u201aMistr Vav\u0159inec Tikal, hodin\xe1\u0159 muzea.\u2018\u201c"],t.s)
B.b8v=new A.a7(B.aI,B.aex,!1)
B.ahw=s(["\u201eVav\u0159inec Tikal! No jist\u011b, to jsem j\xe1! J\xe1 tu\u0161il, \u017ee m\xe1m n\u011bco spole\u010dn\xe9ho s hodinami.\u201c"],t.s)
B.b9f=new A.a7(B.as,B.ahw,!1)
B.aaE=s([B.aqs,B.b8c,B.aqg,B.b8g,B.b9P,B.aq9,B.b8v,B.b9f],t.a)
B.baD=new A.cD("story_12",B.aaE)
B.akR=s(["\u201eV. T.! To vy jste napsal ten vzkaz!\u201c"],t.s)
B.b8J=new A.a7(B.aE,B.akR,!1)
B.apS=new A.b_("Jon\xe1\u0161 mu uk\xe1\u017ee vzkaz ze \u0161atny. Hodin\xe1\u0159 zbledne.")
B.akd=s(["\u201eTo je opravdu moje p\xedsmo. Krasopis! Jedni\u010dka s hv\u011bzdi\u010dkou! Ale kdy bych to psal? A pro\u010d?\u201c"],t.s)
B.b9E=new A.a7(B.as,B.akd,!1)
B.a9Q=s(["\u201eA kdo v\xe1s zav\u0159el?\u201c"],t.s)
B.b7G=new A.a7(B.aE,B.a9Q,!1)
B.ajv=s(["\u201eJedna pan\xed. Byla kr\xe1sn\xe1, ale hrozn\u011b unaven\xe1. Nab\xeddla mi \u0161\xe1lek \u010daje a pak\u2026 u\u017e si nepamatuju nic, jen to, jak se usm\xedvala.\u201c"],t.s)
B.b82=new A.a7(B.as,B.ajv,!1)
B.apH=new A.b_("V\u0161ichni se na sebe pod\xedvaj\xed. Nikdo nic ne\u0159ekne. Ale ka\u017ed\xfd mysl\xed na tot\xe9\u017e. Hodin\xe1\u0159 se zvedne, opr\xe1\u0161\xed si z\xe1st\u011bru a zam\xed\u0159\xed s nimi k hlavn\xedmu s\xe1lu. P\u0159ed n\xedm v\u0161ak jsou ryt\xed\u0159i v pln\xe9 zbroji. Stoj\xed bok po boku a nikoho nepust\xed d\xe1l.")
B.adC=s(["\u201eAch, p\xe1nov\xe9 ryt\xed\u0159i. Velmi d\u016fstojn\xed. A velmi tvrdohlav\xed.\u201c"],t.s)
B.b7v=new A.a7(B.as,B.adC,!1)
B.aq5=new A.b_("Nela zaklepe na brn\u011bn\xed.")
B.aa9=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo?\u201c"],t.s)
B.b90=new A.a7(B.aL,B.aa9,!1)
B.apJ=new A.b_("Brn\u011bn\xed dut\u011b zadun\xed. Ale \u017e\xe1dn\xfd z nich se ani nehne.")
B.ahN=s([B.b8J,B.apS,B.b9E,B.b7G,B.b82,B.apH,B.b7v,B.aq5,B.b90,B.apJ],t.a)
B.baH=new A.cD("story_13",B.ahN)
B.aql=new A.b_("Ryt\xed\u0159i jeden po druh\xe9m zasalutuj\xed a ustoup\xed stranou.")
B.aeq=s(["\u201eOni n\xe1m zasalutovali! Vid\u011bli jste to? Zasalutovali!\u201c"],t.s)
B.b94=new A.a7(B.aE,B.aeq,!1)
B.al5=s(["\u201eRyt\xed\u0159sk\xe1 \u010dest. Pozor! Pohov! R\xe1z, dva, r\xe1z, dva! J\xe1 bych byl dobr\xfd ryt\xed\u0159. Jen by m\u011b ta zbroj tla\u010dila.\u201c"],t.s)
B.b79=new A.a7(B.as,B.al5,!1)
B.aaj=s(["\u201eJe v po\u0159\xe1dku?\u201c"],t.s)
B.b9j=new A.a7(B.aL,B.aaj,!1)
B.ald=s(["\u201eTen \u010daj byl asi hodn\u011b siln\xfd.\u201c"],t.s)
B.b8L=new A.a7(B.aI,B.ald,!1)
B.apy=new A.b_("V\u0161ichni pokra\u010duj\xed d\xe1l do obrovsk\xe9ho s\xe1lu. Je v n\u011bm \u0161ero a podlaha pod nohama zlov\u011bstn\u011b vr\u017ee.")
B.adT=s(["\u201eTuhle podlahu jsem\u2026 opravoval. Nebo jsem ji\u2026 hmm. Tady bych na va\u0161em m\xedst\u011b \u0161el opatrn\u011b. Nev\xedm pro\u010d. Ale \u0161el bych.\u201c"],t.s)
B.b95=new A.a7(B.as,B.adT,!1)
B.ab1=s(["\u201eTo je stra\u0161n\u011b uklid\u0148uj\xedc\xed.\u201c"],t.s)
B.b7V=new A.a7(B.aL,B.ab1,!1)
B.a85=s([B.aql,B.b94,B.b79,B.b9j,B.b8L,B.apy,B.b95,B.b7V],t.a)
B.bb5=new A.cD("story_14",B.a85)
B.apP=new A.b_("Deska se ot\u0159ese a pole se jedno po druh\xe9m propadaj\xed do tmy. K\u016f\u0148 stihne na posledn\xed chv\xedli odsko\u010dit do bezpe\u010d\xed. Z temn\xe9 j\xe1my vylet\xed zlat\xfd \xfalomek kl\xed\u010de se \u0161t\xedtem.")
B.ad_=s(["\u201eBum! To byla ale kr\xe1sa!\u201c"],t.s)
B.b86=new A.a7(B.as,B.ad_,!1)
B.aqL=new A.b_("V\u0161ichni se na n\u011bj pod\xedvaj\xed.")
B.a99=s(["\u201e\u2026Ehm. Pardon. Chci \u0159\xedct: to bylo velmi nebezpe\u010dn\xe9.\u201c"],t.s)
B.b9s=new A.a7(B.as,B.a99,!1)
B.ajl=s(["\u201eA dal\u0161\xed kus.\u201c"],t.s)
B.b7Z=new A.a7(B.aI,B.ajl,!1)
B.ajZ=s(["\u201eA kolik jich jako je\u0161t\u011b m\xe1 b\xfdt?\u201c"],t.s)
B.b9y=new A.a7(B.aL,B.ajZ,!1)
B.aqH=new A.b_("Hodin\xe1\u0159 prom\u011b\u0159uje \xfalomek lupou.")
B.ae6=s(["\u201eKl\xed\u010d\u2026 To je moje pr\xe1ce. Tenhle kl\xed\u010d jsem kdysi vyrobil. Pro\u010d je ulomen\xfd? Kdo by\u2026 Ach ne.\u201c"],t.s)
B.b7u=new A.a7(B.as,B.ae6,!1)
B.ahc=s([B.apP,B.b86,B.aqL,B.b9s,B.b7Z,B.b9y,B.aqH,B.b7u],t.a)
B.baA=new A.cD("story_15",B.ahc)
B.aqY=new A.b_("Cesta k dal\u0161\xedmu s\xe1lu vede p\u0159es vstupn\xed halu. Kolem obrazu baronky proch\xe1zej\xed po \u0161pi\u010dk\xe1ch. Jon\xe1\u0161 se nechce d\xedvat, ale nakonec se stejn\u011b pod\xedv\xe1. Obraz je pr\xe1zdn\xfd. Z\u016fstalo jen osam\u011bl\xe9 k\u0159eslo.")
B.ajC=s(["\u201eKde je?\u201c"],t.s)
B.b7w=new A.a7(B.aI,B.ajC,!1)
B.aqJ=new A.b_("Jon\xe1\u0161 mrkne. A baronka je zase zp\u011bt v obraze. Sp\xed a usm\xedv\xe1 se\u2026")
B.af5=s(["\u201eTo je ona. Pan\xed baronka.\u201c"],t.s)
B.b9i=new A.a7(B.as,B.af5,!1)
B.ajk=s(["\u201eTo ona je ta pan\xed s \u010dajem? Ona v\xe1s zav\u0159ela?\u201c"],t.s)
B.b8E=new A.a7(B.aE,B.ajk,!1)
B.abh=s(["\u201eMo\u017en\xe1\u2026 Nev\xedm. Moje hlava je sam\xe1 d\xedra\u2026 jako ement\xe1l.\u201c"],t.s)
B.b7t=new A.a7(B.as,B.abh,!1)
B.aba=s(["\u201eAle vy jste p\u0159ece ten kl\xed\u010d vyrobil. Kdy\u017e si vzpomenete, zjist\xedme, kde je zbytek!\u201c"],t.s)
B.b7W=new A.a7(B.aE,B.aba,!1)
B.aiZ=s(["\u201eAlchymista m\u011bl naho\u0159e ve v\u011b\u017ei svou laborato\u0159. On m\u011bl v\u017edycky l\xe9k na v\u0161echno.\u201c"],t.s)
B.b7B=new A.a7(B.as,B.aiZ,!1)
B.aeN=s(["\u201eDob\u0159e, jdeme tam.\u201c"],t.s)
B.b6X=new A.a7(B.aE,B.aeN,!1)
B.aqm=new A.b_("Hodin\xe1\u0159 vede d\u011bti po to\u010dit\xfdch schodech nahoru do v\u011b\u017ee, do laborato\u0159e star\xe9ho alchymisty. V laborato\u0159i je ticho a v\u0161ude le\u017e\xed prach.")
B.a8D=s(["\u201eTak, pane alchymisto. Kde m\xe1te ten l\xe9k na v\u0161echno?\u201c"],t.s)
B.b9H=new A.a7(B.aE,B.a8D,!1)
B.a81=s([B.aqY,B.b7w,B.aqJ,B.b9i,B.b8E,B.b7t,B.b7W,B.b7B,B.b6X,B.aqm,B.b9H],t.a)
B.bb2=new A.cD("story_16",B.a81)
B.aq1=new A.b_("V knize jsou t\u0159i recepty. Tenebrikus je lektvar no\u010dn\xedho vid\u011bn\xed. Ardeon je lektvar odvahy. A Siderion je elix\xedr hv\u011bzdn\xe9ho sv\u011btla. Pod n\xe1zvem je drobn\xe9 p\xedsmo.")
B.adk=s(["\u201e\u201aRozjasn\xed mysl a vr\xe1t\xed ztracen\xe9 vzpom\xednky. Spr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch. Polovina d\xe1vky rozjasn\xed mysl. Cel\xe1 d\xe1vka usp\xed na sto let.\u2018\u201c"],t.s)
B.b9N=new A.a7(B.aI,B.adk,!1)
B.apF=new A.b_("Kdy\u017e se obr\xe1t\xed posledn\xed list, le\u017e\xed na n\u011bm zlat\xfd \xfalomek kl\xed\u010de s hv\u011bzdou.")
B.akB=s(["\u201eDal\u0161\xed kus kl\xed\u010de! A k tomu recept na pam\u011b\u0165. Dneska m\xe1me \u0161\u0165astn\xfd den.\u201c"],t.s)
B.b7D=new A.a7(B.aE,B.akB,!1)
B.aiT=s(["\u201eEmo, jsme zav\u0159en\xed v muzeu.\u201c"],t.s)
B.b9a=new A.a7(B.aL,B.aiT,!1)
B.ad2=s(["\u201e\u0160\u0165astn\xfd den v r\xe1mci mo\u017enost\xed.\u201c"],t.s)
B.b8I=new A.a7(B.aE,B.ad2,!1)
B.ai8=s(["\u201e\u201aSpr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch.\u2018 Hv\u011bzdy ale odsud v\u016fbec nejsou vid\u011bt.\u201c"],t.s)
B.b80=new A.a7(B.aI,B.ai8,!1)
B.apY=new A.b_("Nela uk\xe1\u017ee na \xfazk\xe9 sch\u016fdky v rohu.")
B.afI=s(["\u201eCo zkusit schody?\u201c"],t.s)
B.b85=new A.a7(B.aL,B.afI,!1)
B.apE=new A.b_("Sch\u016fdky vedou a\u017e na sam\xfd vrchol v\u011b\u017ee, do mal\xe9 hv\u011bzd\xe1rny. Za velk\xfdm oknem z\xe1\u0159\xed tis\xedce hv\u011bzd.")
B.a9g=s(["\u201eV\u017edy\u0165 je tu milion hv\u011bzd. Co s t\xedm m\xe1me d\u011blat?\u201c"],t.s)
B.b8X=new A.a7(B.aI,B.a9g,!1)
B.a9O=s([B.aq1,B.b9N,B.apF,B.b7D,B.b9a,B.b8I,B.b80,B.apY,B.b85,B.apE,B.b8X],t.a)
B.bb7=new A.cD("story_17",B.a9O)
B.aqO=new A.b_("Souhv\u011bzd\xed na obloze se rozz\xe1\u0159\xed a do v\u011b\u017ee padne st\u0159\xedbrn\xe9 hv\u011bzdn\xe9 sv\u011btlo. Pomalu sklouzne po schodech dol\u016f, a\u017e do alchymistovy laborato\u0159e.")
B.a7O=s(["\u201eTak\u017ee te\u010f asi ty hv\u011bzdy sv\xedt\xed spr\xe1vn\u011b. Kdo by \u0159ekl, \u017ee jdou hv\u011bzdy zapnout.\u201c"],t.s)
B.b8k=new A.a7(B.aL,B.a7O,!1)
B.apI=new A.b_("D\u011bti jdou za sv\u011btlem do laborato\u0159e.")
B.aew=s(["\u201eMn\u011b se to tu nel\xedb\xed. N\u011bkdo n\xe1s tu nechce, c\xedt\xedm to.\u201c"],t.s)
B.b8q=new A.a7(B.aI,B.aew,!1)
B.aaY=s(["\u201eAlchymista m\xedval v\u0161echno p\u0159ipraven\xe9 dop\u0159edu. Jestli ten l\xe9k n\u011bkde bude, tak ur\u010dit\u011b tady.\u201c"],t.s)
B.b8t=new A.a7(B.as,B.aaY,!1)
B.aal=s([B.aqO,B.b8k,B.apI,B.b8q,B.b8t],t.a)
B.bay=new A.cD("story_18",B.aal)
B.aq8=new A.b_("Hodin\xe1\u0159 vypije odm\u011b\u0159enou polovinu elix\xedru. \u0160kytne a v o\u010d\xedch mu zajisk\u0159\xed drobn\xe9 hv\u011bzdi\u010dky.")
B.ahh=s(["\u201eLevandule! Ten \u010daj byl levandulov\xfd. A ona \u0159\xedkala: \u201aBu\u010fte tak laskav, mist\u0159e Tikale. Jenom zastavte hodiny. Jenom na chvilku.\u2018 Potom za\u0161eptala: \u201aJenom nav\u017edy.\u2018 Myslel jsem, \u017ee jsem \u0161patn\u011b rozum\u011bl. A pak\u2026 u\u017e si nic nepamatuju.\u201c"],t.s)
B.b7Q=new A.a7(B.as,B.ahh,!1)
B.af_=s(["\u201eJak\xe9 hodiny?\u201c"],t.s)
B.b9L=new A.a7(B.aI,B.af_,!1)
B.ac6=s(["\u201eTo je\u0161t\u011b nev\xedm. Ale v\xedm, kde to zjist\xedme.\u201c"],t.s)
B.b9C=new A.a7(B.as,B.ac6,!1)
B.aqT=new A.b_("Druhou polovinu elix\xedru hodin\xe1\u0159 pe\u010dliv\u011b zaz\xe1tkuje a schov\xe1 do kapsy z\xe1st\u011bry.")
B.adX=s(["\u201eNa hor\u0161\xed \u010dasy.\u201c"],t.s)
B.b7s=new A.a7(B.as,B.adX,!1)
B.aqU=new A.b_("V tu chv\xedli se ze schodi\u0161t\u011b pod nimi oz\xfdv\xe1 tich\xe9 \u0161ust\u011bn\xed. Pomal\xfdmi kroky jde n\u011bkdo nahoru. V d\xe1lce se oz\xfdv\xe1 ospal\xfd hlas:")
B.ahD=s(["\u201eWas ist das\u2026? Kdo m\u011b to zase ru\u0161\xed\u2026? Ruhe\u2026 Ruhe\u2026\u201c"],t.s)
B.b97=new A.a7(B.vN,B.ahD,!0)
B.afN=s([B.aq8,B.b7Q,B.b9L,B.b9C,B.aqT,B.b7s,B.aqU,B.b97],t.a)
B.baT=new A.cD("story_19",B.afN)
B.aqR=new A.b_("Kroky se zastav\xed za dve\u0159mi a v\u0161ichni ztuhnou. Ozve se jen dlouh\xe9, ospal\xe9 z\xedvnut\xed. Pak \u0161ust\u011bn\xed sukn\xed pomalu sl\xe1bne, a\u017e utichne \xfapln\u011b.")
B.aho=s(["\u201eJe pry\u010d. Vr\xe1tila se do obrazu. O\u010dividn\u011b moc dlouho venku nevydr\u017e\xed.\u201c"],t.s)
B.b9W=new A.a7(B.aI,B.aho,!1)
B.ado=s(["\u201eTak toho vyu\u017eijeme. Rychle dol\u016f!\u201c"],t.s)
B.b8F=new A.a7(B.aE,B.ado,!1)
B.aqh=new A.b_("D\u011bti jdou tmou za hodin\xe1\u0159em. Vede je dlouhou chodbou a\u017e k n\xedzk\xfdm dve\u0159\xedm.")
B.abn=s(["\u201eMoje d\xedlna! Kdo mi tady ud\u011blal takov\xfd nepo\u0159\xe1dek? Aha. J\xe1. Tady b\xfdval v\u017edycky po\u0159\xe1dek. Ka\u017ed\xe9 hodiny v\u011bd\u011bly, kolik je hodin. Te\u010f nev\u011bd\xed nic. Ani jedny. Jako j\xe1.\u201c"],t.s)
B.b74=new A.a7(B.as,B.abn,!1)
B.afu=s([B.aqR,B.b9W,B.b8F,B.aqh,B.b74],t.a)
B.baR=new A.cD("story_20",B.afu)
B.apz=new A.b_("N\xe1st\u011bnn\xe9 hodiny odbij\xed p\u016flnoc a v\u0161echny bud\xedky se ozvou s nimi. Zvon\xed, cinkaj\xed a rachot\xed. Pak v\u0161echny zase ztichnou a ru\u010di\u010dky se znovu zastav\xed. A na podlaze pod pracovn\xedm stolem n\u011bco le\u017e\xed.")
B.akV=s(["\u201eMoje bed\xfdnka! Moje sou\u010d\xe1stky! Pades\xe1t let jsem je t\u0159\xeddil!\u201c"],t.s)
B.b8s=new A.a7(B.as,B.akV,!1)
B.aqn=new A.b_("Hodin\xe1\u0159 si k bed\xfdnce klekne a n\u011b\u017en\u011b ji hlad\xed.")
B.abV=s(["\u201eTahle bed\xfdnka byla v\u017edycky na sv\xe9m m\xedst\u011b. A v\u0161echno v n\xed taky.\u201c"],t.s)
B.b9b=new A.a7(B.as,B.abV,!1)
B.aeX=s([B.apz,B.b8s,B.aqn,B.b9b],t.a)
B.bb3=new A.cD("story_21",B.aeX)
B.aqc=new A.b_("Posledn\xed sou\u010d\xe1stka zapadne na sv\xe9 m\xedsto a pod bed\xfdnkou se zaleskne zlat\xfd \xfalomek kl\xed\u010de s kole\u010dkem. Hodin\xe1\u0159 vezme bed\xfdnku do rukou. Chv\xedli se na ni d\xedv\xe1. A pak se mu v o\u010d\xedch rozsv\xedt\xed. Tentokr\xe1t doopravdy.")
B.aaF=s(["\u201eU\u017e si vzpom\xedn\xe1m. Na v\u0161echno. Za orlojem je tajn\xe1 chodba, kter\xe1 vede k srdci muzea.\u201c"],t.s)
B.b7d=new A.a7(B.as,B.aaF,!1)
B.alg=s(["\u201eBaronka m\u011b p\u0159inutila ho zastavit a zape\u010detit. Od t\xe9 chv\xedle je tu po\u0159\xe1d p\u016flnoc. R\xe1no nikdy nep\u0159ijde a dve\u0159e se nikdy neotev\u0159ou.\u201c"],t.s)
B.b8Q=new A.a7(B.as,B.alg,!1)
B.ajf=s(["\u201eA kl\xed\u010d?\u201c"],t.s)
B.b8f=new A.a7(B.aI,B.ajf,!1)
B.acR=s(["\u201eTen rozlomila ona. Kousek po kousku roznesla \xfalomky po muzeu a u ka\u017ed\xe9ho nastra\u017eila past, aby u\u017e nikdo nemohl srdce muzea znovu probudit. A j\xe1 hlup\xe1k j\xed je\u0161t\u011b sv\xedtil na cestu.\u201c"],t.s)
B.b7Y=new A.a7(B.as,B.acR,!1)
B.a7i=s(["\u201eJen jednou se mi na chv\xedli rozjasnilo v hlav\u011b. Rychle jsem napsal vzkaz a schoval ho do sk\u0159\xed\u0148ky v \u0161atn\u011b, kde by ho baronka nikdy nehledala. Stihl jsem to t\u011bsn\u011b p\u0159edt\xedm, ne\u017e mi poru\u010dila, a\u0165 se zav\u0159u za m\u0159\xed\u017e. A pak u\u017e jsem si nepamatoval nic.\u201c"],t.s)
B.b8M=new A.a7(B.as,B.a7i,!1)
B.al_=s(["\u201eAle pro\u010d to ud\u011blala?\u201c"],t.s)
B.b8Z=new A.a7(B.aE,B.al_,!1)
B.a9y=s([B.aqc,B.b7d,B.b8Q,B.b8f,B.b7Y,B.b8M,B.b8Z],t.a)
B.bb8=new A.cD("story_22",B.a9y)
B.ajm=s(["\u201eZ\xedtra r\xe1no ji maj\xed odv\xe9zt do nov\xe9 galerie na n\xe1dra\u017e\xed. Mezi vlaky, hl\xe1\u0161en\xed a tis\xedce lid\xed. L\xe9ta tady nem\u016f\u017ee usnout kv\u016fli n\xe1v\u0161t\u011bvn\xedk\u016fm. A tam by neusnula u\u017e nikdy.\u201c"],t.s)
B.b8T=new A.a7(B.as,B.ajm,!1)
B.adS=s(["\u201eTo je vlastn\u011b\u2026 trochu smutn\xe9.\u201c"],t.s)
B.b76=new A.a7(B.aE,B.adS,!1)
B.aj5=s(["\u201eJen\u017ee j\xed je \xfapln\u011b jedno, \u017ee tu n\u011bkoho zamkne. A \u017ee se muzeum u\u017e nikdy neotev\u0159e. To je teda p\u011bkn\u011b sobeck\xe9.\u201c"],t.s)
B.b7b=new A.a7(B.aL,B.aj5,!1)
B.aq3=new A.b_("Hodin\xe1\u0159 je zavede do rohu d\xedlny. Stoj\xed tam orloj, na kter\xe9m hodin\xe1\u0159 pracoval cel\xfd \u017eivot. Te\u010f ml\u010d\xed.")
B.adt=s(["\u201eMoje nejkr\xe1sn\u011bj\u0161\xed pr\xe1ce. A cesta k srdci muzea. Jen\u017ee jsem ho musel rozebrat.\u201c"],t.s)
B.b7M=new A.a7(B.as,B.adt,!1)
B.ah0=s(["\u201eTak to oprav\xedme. Ur\u010dit\u011b to nebude t\u011b\u017ek\xe9.\u201c"],t.s)
B.b7q=new A.a7(B.aE,B.ah0,!1)
B.abf=s(["\u201eTo sam\xe9 jsi \u0159\xedkala o tom pl\xe1nu se \u0161atnou. A pod\xedvej, kde jsme.\u201c"],t.s)
B.b8B=new A.a7(B.aL,B.abf,!1)
B.aco=s([B.b8T,B.b76,B.b7b,B.aq3,B.b7M,B.b7q,B.b8B],t.a)
B.baU=new A.cD("story_23",B.aco)
B.aq0=new A.b_("Orloj se nadechne. Ru\u010di\u010dky se rozeb\u011bhnou a dv\xed\u0159ka dole se pomalu otev\u0159ou. Za nimi je \xfazk\xe1 chodba a na jej\xedm konci podivn\xe9 sv\u011btlo.")
B.akf=s(["\u201eTajn\xe1 chodba! Poj\u010fte!\u201c"],t.s)
B.b7x=new A.a7(B.aE,B.akf,!1)
B.aqK=new A.b_("Chodba za orlojem kon\u010d\xed ve skryt\xe9 hale s vysok\xfdm stropem. Uprost\u0159ed zdi vis\xed obrovsk\xe9 hodiny, p\u0159es cifern\xedk maj\xed rudou pe\u010de\u0165.")
B.aiH=s(["\u201eSrdce muzea.\u201c"],t.s)
B.b8N=new A.a7(B.as,B.aiH,!1)
B.aq4=new A.b_("Za jejich z\xe1dy za\u0161ust\xed \u0161aty.")
B.aqV=new A.b_("Ve dve\u0159\xedch haly stoj\xed baronka Frida von Schlafenberg. Skute\u010dn\xe1 a \u017eiv\xe1, vystoupila z obrazu. Je mnohem vy\u0161\u0161\xed, ne\u017e si mysleli. A hrozn\u011b, hrozn\u011b ospal\xe1.")
B.ahi=s(["\u201eKinder\u2026 D\u011bti. Pro\u010d jste tak hlu\u010dn\xe9? Sto let. Sto let jsem neusnula. Nechte ty hodiny sp\xe1t. Bitte\u2026\u201c"],t.s)
B.b83=new A.a7(B.vN,B.ahi,!1)
B.aqM=new A.b_("Ema ud\u011bl\xe1 krok dop\u0159edu a postav\xed se p\u0159ed ostatn\xed. Baronka k n\xed nat\xe1hne ruku. Ale v p\u016fli pohybu se j\xed zav\u0159ou o\u010di. Pomalu se sesune na schod, polo\u017e\xed hlavu na ruku\u2026 a usne. Jej\xed postava zbledne, zpr\u016fhledn\xed a rozplyne se.")
B.adL=s(["\u201eVr\xe1tila se do obrazu?\u201c"],t.s)
B.b9w=new A.a7(B.aL,B.adL,!1)
B.ab5=s(["\u201eVypad\xe1 to tak. Ale nev\xedme, na jak dlouho.\u201c"],t.s)
B.b7j=new A.a7(B.aI,B.ab5,!1)
B.abZ=s(["\u201eTak si mus\xedme posp\xed\u0161it. Pom\u016f\u017eete star\xe9mu hodin\xe1\u0159i? Je\u0161t\u011b naposledy?\u201c"],t.s)
B.b9k=new A.a7(B.as,B.abZ,!1)
B.ajQ=s([B.aq0,B.b7x,B.aqK,B.b8N,B.aq4,B.aqV,B.b83,B.aqM,B.b9w,B.b7j,B.b9k],t.a)
B.baw=new A.cD("story_24",B.ajQ)
B.aq2=new A.b_("\xdalomky se zatav\xed do vosku a pe\u010de\u0165 se rozz\xe1\u0159\xed. Pak praskne a rozlet\xed se na kusy. Pod n\xed se objev\xed cifern\xedk. Ru\u010di\u010dky ukazuj\xed p\u016flnoc. Hodiny se zhluboka nadechnou\u2026 a rozb\u011bhnou se. Po cel\xe9m muzeu se rozezn\xed tik\xe1n\xed v\u0161ech hodin najednou. Ru\u010di\u010dky ute\u010dou od p\u016flnoci, v okn\u011b chodby je vid\u011bt \xfasvit a z\xe1mky v\u0161ech dve\u0159\xed v muzeu cvaknou.")
B.aiR=s(["\u201eSly\u0161\xedte to? Muzeum zase d\xfdch\xe1. Srdce muzea je tajemstv\xed, nikdo ho tu nesm\xed naj\xedt a v\xe1s tak\xe9 ne. Tuhle chodbu zase schov\xe1m. Z\u016fstanu tady a d\xe1m do po\u0159\xe1dku v\u0161echno, co tu baronka provedla. Hodiny u\u017e nikomu nedovol\xedm zastavit. Ani za \u0161\xe1lek levandulov\xe9ho \u010daje.\u201c"],t.s)
B.b96=new A.a7(B.as,B.aiR,!1)
B.ahP=s(["\u201eA posp\u011b\u0161te si. Baronka te\u010f tvrd\u011b sp\xed. Ale dokud je muzeum zav\u0159en\xe9, m\u016f\u017ee kdykoli vystoupit z obrazu. Otev\u0159ete hlavn\xed dve\u0159e, ne\u017e se vzbud\xed.\u201c"],t.s)
B.b8m=new A.a7(B.as,B.ahP,!1)
B.aeW=s([B.aq2,B.b96,B.b8m],t.a)
B.baQ=new A.cD("story_25",B.aeW)
B.aqA=new A.b_("Ema ho obejme. Jon\xe1\u0161 mu pod\xe1 ruku. Nela mu vyt\xe1hne pavu\u010dinu z vlas\u016f. Zvenku se ozve motor n\xe1kladn\xedho auta, st\u011bhov\xe1ci p\u0159ijeli pro obraz baronky. D\u011bti b\u011b\u017e\xed zp\xe1tky do vstupn\xed haly. Baronka v obraze sp\xed a usm\xedv\xe1 se. Jen\u017ee hlavn\xed dve\u0159e se po\u0159\xe1d nehnou.")
B.ac1=s(["\u201eZ\xe1mky p\u0159ece cvakly. Tak pro\u010d se ty dve\u0159e neotev\u0159ou?\u201c"],t.s)
B.b8Y=new A.a7(B.aL,B.ac1,!1)
B.ajq=s(["\u201eH\xe1d\xe1m, \u017ee tohle je posledn\xed past pan\xed baronky.\u201c"],t.s)
B.b70=new A.a7(B.aE,B.ajq,!1)
B.aqd=new A.b_("Baronka v obraze se zavrt\xed a ze span\xed vzdychne. D\u011bti ztuhnou.")
B.abH=s(["\u201eRychle. A potichu.\u201c"],t.s)
B.b8h=new A.a7(B.aE,B.abH,!1)
B.ah8=s([B.aqA,B.b8Y,B.b70,B.aqd,B.b8h],t.a)
B.baZ=new A.cD("story_26",B.ah8)
B.aqX=new A.b_("Posledn\xed z\xe1str\u010dka cvakne. T\u011b\u017ek\xe1 k\u0159\xeddla dve\u0159\xed se pomalu otev\u0159ou a do haly vtrhne rann\xed sv\u011btlo. Rozlije se po podlaze, po zdech a nakonec dopadne i na obraz.")
B.afh=s(["\u201eJe otev\u0159eno! Muzeum je otev\u0159en\xe9!\u201c"],t.s)
B.b9T=new A.a7(B.aE,B.afh,!1)
B.ae0=s(["\u201ePod\xedvejte na obraz. Pan\xed baronce n\u011bjak ztuhl \xfasm\u011bv.\u201c"],t.s)
B.b9x=new A.a7(B.aL,B.ae0,!1)
B.apG=new A.b_("Tv\xe1\u0159 baronky se pomalu zamra\u010d\xed. U\u017e se nepohne.")
B.acY=s(["\u201eTak to bychom m\u011bli. A te\u010f honem pry\u010d, ne\u017e n\xe1s tu n\u011bkdo najde.\u201c"],t.s)
B.b8d=new A.a7(B.aI,B.acY,!1)
B.aqe=new A.b_("D\u011bti vyklouznou z muzea ve chv\xedli, kdy st\u011bhov\xe1ci vystupuj\xed z auta.")
B.ak1=s(["\u201eZvl\xe1dli jsme to!\u201c"],t.s)
B.b9d=new A.a7(B.aE,B.ak1,!1)
B.apZ=new A.b_("St\u011bhov\xe1ci vejdou do muzea, po chv\xedli vyn\xe1\u0161\xed velk\xfd obraz zabalen\xfd do deky. Jeden roh deky sklouzne.")
B.apX=new A.b_("Baronka Frida von Schlafenberg sice sp\xed, ale tv\xe1\u0159\xed se tak na\u0161tvan\u011b jako je\u0161t\u011b nikdy. V\u0161imnou si toho i st\u011bhov\xe1ci. \u201eNa n\xe1dra\u017e\xed si zvykne,\u201c prohod\xed jeden ze st\u011bhov\xe1k\u016f. Potom, co auto odjede, se v okn\u011b muzea na okam\u017eik objev\xed star\xfd hodin\xe1\u0159 s lampou. K\xfdvne na n\u011b, zamrk\xe1 a zmiz\xed. Z muzea je sly\u0161et tich\xe9, spokojen\xe9 tik\xe1n\xed.")
B.ak8=s(["\u201eTohle n\xe1m nikdo neuv\u011b\u0159\xed.\u201c"],t.s)
B.b75=new A.a7(B.aL,B.ak8,!1)
B.ail=s([B.aqX,B.b9T,B.b9x,B.apG,B.b8d,B.aqe,B.b9d,B.apZ,B.apX,B.b75],t.a)
B.baX=new A.cD("story_27",B.ail)
